SELECT s.id as scheduleId, d.name as doctorName, c.name as departmentName, s.schedule_date as date, s.time_slot as timeSlot, CASE WHEN s.time_slot = 'MORNING' THEN '09:00' WHEN s.time_slot = 'AFTERNOON' THEN '14:00' WHEN s.time_slot = 'EVENING' THEN '18:00' ELSE '09:00' END as startTime, CASE WHEN s.time_slot = 'MORNING' THEN '12:00' WHEN s.time_slot = 'AFTERNOON' THEN '17:00' WHEN s.time_slot = 'EVENING' THEN '21:00' ELSE '12:00' END as endTime, s.available_slots as availableSlots, s.total_slots as totalSlots, 50.0 as fee, 5.0 as discountedFee FROM schedule s LEFT JOIN doctor d ON s.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id WHERE s.schedule_date >= #{startDate} AND s.schedule_date <= #{endDate} AND s.available_slots > 0
AND c.id = #{departmentId}
AND s.doctor_id = #{doctorId}
AND s.time_slot = #{timeSlot}
ORDER BY s.schedule_date, s.time_slot

SELECT s.id, s.doctor_id as doctorId, d.name as doctorName, dept.id as departmentId, dept.name as departmentName, c.id as clinicId, c.name as clinicName, s.schedule_date as scheduleDate, s.time_slot as timeSlot, s.slot_type as slotType, s.total_slots as totalSlots, s.available_slots as availableSlots FROM schedule s LEFT JOIN doctor d ON s.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id LEFT JOIN department dept ON c.department_id = dept.id
AND s.doctor_id = #{doctorId}
AND dept.id = #{departmentId}
AND s.schedule_date >= #{startDate}
AND s.schedule_date <= #{endDate}
AND s.time_slot = #{timeSlot}
AND s.slot_type = #{slotType}
ORDER BY s.schedule_date DESC, s.time_slot

SELECT COUNT(*)
FROM schedule s

    LEFT JOIN doctor d ON s.doctor_id = d.id



        AND s.doctor_id = #{doctorId}


        AND d.clinic_id = #{departmentId}


        AND s.schedule_date >= #{startDate}


        AND s.schedule_date <= #{endDate}


        AND s.time_slot = #{timeSlot}


        AND s.slot_type = #{slotType}
